au(P, 1, title="IP ownership and chain of title, including AI-generated code",
   status="unknown",
   rationale="The formation values file lists 'IP assigned to this LLC', 'IP licensed to this LLC' and 'IP explicitly excluded' as TODO. Echelon components are published under licenses naming a licensor, but which person or entity holds title was not established. AI agents produce material portions of repository work (Praxis provenance).",
   target="Echelon Foundry, LLC holds title to all Echelon software through a recorded founder IP assignment and invention assignment agreements with every person and contractor who contributes. Pre-existing IP retained by any person is listed and licensed to the company perpetually and irrevocably. Contributions produced with AI tools are identified through provenance records; we rely on the human authorship, selection and arrangement in our works and on AI provider terms that assign outputs to us, and we acknowledge that purely machine-generated portions may not be copyrightable. No security interest encumbers the IP.",
   current="Unknown; title holder of Echelon IP is not established.",
   intended="Execute founder assignment at formation; adopt contributor assignment for all contributors.",
   provable="Praxis provenance records identify agent versus human contributions in repositories, which supports but does not establish chain of title.",
   statement="IP ownership documentation is not yet complete. A founder IP assignment to Echelon Foundry, LLC and contributor assignment agreements are planned.",
   kind="planned", controls=["IPR-002"], evrs=["IPR-001"],
   freshness="per-event", mechanism="periodic-manual", automation="partial", impl="low", recur="low",
   oq=["US Copyright Office guidance on AI-generated works is not seeded as a source.", "Is the licensor of record on Echelon components an individual or the LLC?"],
   qd=dict(sub="IP ownership", concern="The vendor has the rights it purports to license.",
           risk="A third party, founder or former contributor asserts rights in the software, disrupting the customer's use.",
           src=[S("SRC-ISO-27001-2022", "A.5.32", "informed-by"), S("SRC-SA-SIG", rel="informed-by"), D("SRC-ECH-BUSINESS-PLAN", rel="informed-by")],
           ind=ALLI, prod=ALLP, imp="high"),
   questions=[
    Q("Does your company own all IP in the service, or is any of it owned by founders, affiliates or third parties and licensed to you?",
      ["Who owns the software you are licensing to us?"], imp="critical"),
    Q("Have all founders, employees and contractors signed agreements assigning their inventions and copyrights to the company?",
      ["Do you have invention assignment agreements with all contributors?"]),
    Q("How do you address ownership and copyrightability of code produced by AI agents in your products?",
      ["Do you own code written by AI tools?"], src=[S("SRC-NIST-AI-600-1", rel="informed-by"), S("SRC-NIST-SP800-218A", rel="informed-by")], rc="customer-preference"),
    Q("Are there liens, security interests or prior exclusive licenses that restrict your ability to license the IP to us?",
      ["Is your IP pledged as collateral?"], imp="medium"),
   ])

au(P, 2, title="Echelon component licensing, including PolyForm Noncommercial terms",
   status="proposed-target-state",
   rationale=f"The Unbound capability assessment ({CAP}) records that every inspected Echelon system except the Registry (MIT), the Echelon Diagnostic Framework (MIT) and the Echelon theme (UNLICENSED) is licensed under PolyForm Noncommercial 1.0.0, and that commercial licensing is a launch blocker. CNV-GOV-009 forbids release-1 production dependencies under a noncommercial license without an executed commercial license plus escrow or a fork right. It also records version mismatches between tags, registry and vendored copies. The Secure Construction Standard separately says to prefer MIT for original public tooling, which conflicts with current practice.",
   target="Customers receive a written commercial license from Echelon Foundry, LLC covering every Echelon component in their deployment (including Limen, Forma, Folio, Strata, Praxis-derived tooling), regardless of the public PolyForm Noncommercial license, with escrow release and a perpetual fork right for the customer's own use if Echelon ceases to support it. Each deployment carries an SBOM that names every Echelon component by tagged release and digest and the license under which the customer holds it; the release check fails if a PolyForm Noncommercial component lacks a commercial license record (CNV-GOV-009 AC-1). The licensor of record on public licenses is the LLC.",
   current="Echelon components are publicly licensed under PolyForm Noncommercial 1.0.0. No commercial license has been executed or offered. Component versions are inconsistent across tags, registry and vendored copies.",
   intended="Draft a commercial license and attach it to customer agreements; align public license licensor to the LLC; pin dependencies to tagged releases with digests.",
   provable="The public license files and the capability assessment establish the noncommercial licensing; nothing establishes commercial rights.",
   statement="Most Echelon components are currently published under the PolyForm Noncommercial 1.0.0 license. A commercial license covering customer production use is not yet available; we will not ask a customer to rely on the noncommercial license for production use.",
   kind="not-available", controls=["IPR-001"], evrs=["IPR-003", "IPR-002", "IPR-005"],
   policies=["SEC-SUPPLY-001"], requirements=["CNV-GOV-009"], freshness="per-event", mechanism="event-driven-automated",
   automation="high", impl="low", recur="none",
   residual=["Whether a nonprofit's own use qualifies as noncommercial under PolyForm terms is a legal question; relying on it for a vendor-operated service is unsafe."],
   oq=["PolyForm Noncommercial 1.0.0 is not seeded as a source (needed: SRC id for the license text).",
       "Should the Secure Construction Standard's preference for MIT be reconciled with the PolyForm Noncommercial licensing of the stack?"],
   challenge=CH(
     customer_intent="Certainty that the customer has lawful, durable rights to use everything in its deployment.",
     adverse_outcome="Customer's production use is outside the license, or rights end when the vendor relationship ends.",
     conventional_control_effectiveness="Conventional vendors license proprietary code under the MSA; Echelon's public noncommercial license is unusual and must be superseded explicitly.",
     legally_required="Copyright law requires a license for use beyond the public grant; no regulation addresses it.",
     contractually_required="Customers routinely require warranties of title and non-infringement.",
     historical_convention="Proprietary license in the MSA plus escrow.",
     architectural_elimination="Thin dependency boundaries allow replacement of a component (capability assessment fallback).",
     automatic_enforcement="SBOM license gate fails releases containing unlicensed PolyForm components.",
     continuous_evidence="Per-release SBOM with license field and gate result.",
     stronger_alternative="Commercial license plus fork right plus SBOM gate.",
     alternative_verifiable="Yes, by inspecting SBOMs and executed licenses.",
     customer_acceptance_likelihood="Likely once a commercial license exists; unlikely before.",
     invalidating_conditions="Licensor of record is not the contracting entity; versions in deployment differ from licensed versions.",
     conventional_cost="Low legal drafting cost.",
     alternative_cost="Low.",
     alternative_risks="Customers may question why the public license is noncommercial and whether community contributions complicate title.",
     supporting_arguments=["Source availability lets customers inspect what they run."],
     opposing_arguments=["Procurement and legal teams may flag any noncommercial license in the supply chain as a blocker regardless of a side license."],
     technical_effectiveness="equivalent", institutional_acceptance="uncertain"),
   qd=dict(sub="Echelon licensing", concern="The customer holds valid rights for its actual use of every vendor component.",
           risk="Customer uses components outside their license terms, or loses rights at exit.",
           src=[D("SRC-ECH-UNB-BASELINE"), S("SRC-SPDX", rel="informed-by")], ind=ALLI, prod=ALLP, imp="critical"),
   questions=[
    Q("Under what license terms will we use your software, and do any components carry noncommercial, source-available or other restrictive licenses?",
      ["Provide the license terms for every component we will use."]),
    Q("Several of your published components are licensed under PolyForm Noncommercial 1.0.0. What commercial license grants us the right to use them in our production service?",
      ["How do PolyForm Noncommercial terms affect our commercial use?"]),
    Q("We are a nonprofit. Does a noncommercial license cover our use of your components, or do we still need a commercial license from you?",
      ["Can a charity rely on your noncommercial license?"], ind=DAF, rc="customer-preference", imp="high"),
    Q("Which tagged release of each Echelon component is in our deployment, and does the license we hold match that release?",
      ["Provide component versions and digests with their licenses."], src=[D("SRC-ECH-UNB-BASELINE"), S("SRC-NTIA-SBOM-MIN", rel="informed-by")], imp="medium"),
    Q("Who is the licensor of record for your components: the company or an individual?",
      ["Which legal person grants the license?"], imp="medium", prod=ORG),
   ])

