au(P, 4, title="Customer data ownership, permitted use and AI training rights",
   status="proposed-target-state",
   rationale="Business plan section 10.04 separates service use, retention, learning, evaluation, model training and publication rights as a draft position. Unbound requires third-party data rights and permitted AI use to be enforced in access, storage, retrieval and exports (SOC2-028) and a source registry with license and terms (UNB-EXT-017). Nothing is implemented, and the AI providers Echelon would use are not inventoried.",
   target="Customers own their data and all outputs generated from it. Echelon uses customer data only to provide the service. Customer, donor, advisor and grantee data is never used to train, fine-tune or evaluate AI models, ours or a provider's, and is sent only to AI providers whose contract prohibits training on it and limits retention, verified per provider and per model endpoint. Aggregated or de-identified use for benchmarking requires the customer's opt-in. Purpose restrictions are enforced in the data access layer so that analytics or training pipelines cannot read tenant data without a recorded purpose grant. Third-party data license restrictions travel with the data into display, storage and export.",
   current="Not established.",
   intended="Contract terms plus purpose-bound data access in Unbound; AI provider inventory with training terms.",
   provable="Requirements and draft plan text only.",
   statement="Echelon does not intend to use customer data to train AI models and plans to make that a contractual commitment enforced in the platform. These commitments are not yet contractually offered or implemented.",
   kind="planned", controls=["IPR-003", "IPR-004"], evrs=["IPR-004"],
   requirements=["SOC2-028", "UNB-EXT-017"], freshness="P90D", mechanism="periodic-automated", automation="high",
   impl="medium", recur="low",
   challenge=CH(
     customer_intent="Donor and sponsor data is not used to benefit others or exposed through AI models.",
     adverse_outcome="Customer data appears in model outputs for other parties or is commercialized.",
     conventional_control_effectiveness="Contract clauses alone depend on the vendor's and AI provider's discipline and cannot be observed by the customer.",
     legally_required="Not directly, but privacy laws (GLBA, state privacy laws, CCPA service provider terms) restrict secondary use.",
     contractually_required="Increasingly common in enterprise and financial services contracts.",
     historical_convention="Contractual no-training clause.",
     architectural_elimination="Tenant data reachable only through purpose-bound interfaces; no pipeline exists that exports tenant data to training.",
     automatic_enforcement="Data access layer denies reads without a purpose grant; egress allowlist limits AI endpoints to approved no-training configurations.",
     continuous_evidence="Access logs with purpose, egress logs, provider configuration attestations.",
     stronger_alternative="Contract plus architectural purpose enforcement plus egress control.",
     alternative_verifiable="Partially; customers rely on logs and assessments.",
     customer_acceptance_likelihood="Likely.",
     invalidating_conditions="Provider changes default retention or training terms; shadow use of AI tools by personnel.",
     conventional_cost="Low.",
     alternative_cost="Medium engineering.",
     alternative_risks="Purpose enforcement could hinder legitimate support work.",
     supporting_arguments=["Makes the promise checkable."],
     opposing_arguments=["Customers cannot independently observe AI provider retention."],
     technical_effectiveness="stronger", institutional_acceptance="likely"),
   qd=dict(sub="Customer data and AI training rights", concern="Customer data is used only for the customer's purposes.",
           risk="Customer or donor data is reused, commercialized or used to train AI models without authorization.",
           src=[D("SRC-ECH-BUSINESS-PLAN"), D("SRC-ECH-UNB-SOC2-DIRECTIVE"), S("SRC-NIST-AI-RMF-1.0", rel="informed-by"), S("SRC-GLBA", rel="informed-by")],
           ind=ALLI, prod=ALLP, imp="critical"),
   questions=[
    Q("Who owns our data and the outputs derived from it, such as reports, statements and analytics?",
      ["Do we retain ownership of our data?"], imp="high"),
    Q("Will you use our data, or our donors', advisors' or grantees' data, to train, fine-tune or evaluate any AI model, yours or a third party's?",
      ["Is our data used for AI training?"]),
    Q("Do the AI model providers you use retain or train on prompts and outputs that contain our data, and what contract terms and configurations prevent it?",
      ["What are your AI providers' data retention terms?"], src=[S("SRC-CSA-AICM", rel="informed-by"), S("SRC-OWASP-LLM-TOP10-2025", rel="informed-by")]),
    Q("Will you use aggregated or de-identified data derived from our data for benchmarking or product improvement, and can we opt out?",
      ["Do you use anonymized customer data?"], imp="medium", rc="customer-preference"),
    Q("What rights do you claim in configurations, workflows, policy packs or feedback that we create in or provide about the service?",
      ["Who owns our configurations and feedback?"], imp="medium", rc="customer-preference"),
    Q("How do you honor license restrictions on third-party data, such as charity data sources, in what the service displays, stores and exports?",
      ["Do third-party data licenses limit what we can export?"], ind=DAF, prod=UNB, src=[D("SRC-ECH-UNB-BASELINE"), D("SRC-ECH-UNB-SOC2-DIRECTIVE")]),
   ])

