au(HRC, 2, title="Security, privacy and role-specific training",
   status="unknown", rationale=NOHR,
   target="All personnel complete security and privacy awareness training at onboarding and annually, covering phishing, social engineering, data handling, incident reporting and acceptable use of AI tools. Engineers complete role training on the Secure Construction Standard rules and the reasons behind them (F# domain types, Strata-only database access, Limen boundary, no HTML input), and personnel handling donor or financial data complete GLBA, privacy and fraud red-flag training. Effectiveness is measured by phishing simulation and by defects caught by gates rather than reviewers. Because the most important rules are enforced by construction, training focuses on judgment that structure cannot provide.",
   current="Unknown.",
   intended="Adopt a training curriculum and tracking before production.",
   provable="Nothing.",
   statement="A security awareness and role-based training program is planned but not yet in place.",
   kind="planned", controls=["HR-005"], evrs=["HR-002"],
   policies=["SEC-DB-001", "SEC-UI-001", "SEC-UI-002"], freshness="P1Y", mechanism="periodic-automated", automation="high",
   impl="low", recur="low",
   challenge=CH(
     customer_intent="Personnel do not cause incidents through ignorance.",
     adverse_outcome="Phishing or insecure coding leads to a breach.",
     conventional_control_effectiveness="Annual awareness training has modest measured effect; secure coding training does not reliably prevent injection flaws.",
     legally_required="The FTC Safeguards Rule requires financial institutions to provide security awareness training to their own personnel; customers flow it to vendors by contract.",
     contractually_required="Common.",
     historical_convention="Annual training with completion certificates.",
     architectural_elimination="Restricted interfaces make classes of coding errors unavailable (SEC-DB-001, SEC-UI-001), and phishing-resistant authenticators blunt credential phishing.",
     automatic_enforcement="Build gates enforce rules regardless of training.",
     continuous_evidence="Gate results and phishing simulation metrics.",
     stronger_alternative="Structure plus targeted training on residual judgment areas.",
     alternative_verifiable="Yes.",
     customer_acceptance_likelihood="Likely as a complement; completion records are still expected.",
     invalidating_conditions="Gates not actually enforced.",
     conventional_cost="Low.",
     alternative_cost="Engineering cost shared with SEC rules.",
     alternative_risks="Overreliance on structure for non-code risks such as social engineering of payment changes.",
     supporting_arguments=["Training time is spent where structure cannot help."],
     opposing_arguments=["Auditors test completion, not effectiveness."],
     technical_effectiveness="stronger", institutional_acceptance="likely"),
   qd=dict(sub="Training and awareness", concern="Personnel know how to protect customer data and recognize threats.",
           risk="Human error or susceptibility to social engineering causes an incident.",
           src=[S("SRC-NIST-CSF-2.0", "PR.AT-01"), S("SRC-ISO-27001-2022", "A.6.3"), S("SRC-NIST-SP800-53-R5", "AT-2"), S("SRC-CSA-CCM-V4", "HRS-11"), S("SRC-SA-SIG", rel="informed-by")],
           ind=ALLI, prod=ORG),
   questions=[
    Q("Do all personnel complete security and privacy awareness training at hire and at least annually? Provide completion rates.",
      ["Do you have a security awareness program?"]),
    Q("Do engineers receive secure development training specific to your technology stack, such as F#, .NET, PostgreSQL and browser execution boundaries?",
      ["Is secure coding training required for developers?"], src=[S("SRC-NIST-SP800-53-R5", "AT-3"), S("SRC-NIST-SP800-218", rel="informed-by"), D("SRC-ECH-SCS-0.1")], imp="medium", prod=ALLP),
    Q("Do personnel who handle donor or financial data receive training on GLBA, privacy and fraud red flags?",
      ["Is there specialized training for staff with access to financial data?"],
      src=[D("SRC-FTC-SAFEGUARDS-RULE", "16 CFR 314.4(e)"), S("SRC-SEC-REG-S-ID", rel="informed-by")], ind=FIN + DAF, rc="contractual-common"),
    Q("How do you measure whether training changes behavior, for example through phishing simulations?",
      ["Do you run phishing tests?"], imp="medium", rc="customer-preference"),
   ])

