au(HRC, 4, title="Joiner, mover and leaver access lifecycle across all systems",
   status="unknown", rationale=NOHR + " Unbound requires provisioning and deprovisioning coverage including service and agent identities (SOC2-010).",
   target="A single identity source drives access to every system: SSO, cloud consoles, code hosting, CI, package registries, AI tool accounts and support tools. Departures trigger revocation of all accounts, sessions, personal access tokens, SSH and API keys within one hour for involuntary and by end of last day for voluntary departures, with secrets the person could see rotated. A daily reconciliation compares active accounts and credentials in every system against the identity source and alerts on orphans. Role changes remove access not needed in the new role. Contractor end dates are recorded at engagement and access expires automatically. Devices are recovered or remotely wiped.",
   current="Unknown.",
   intended="Establish identity source and reconciliation as part of Unbound operations readiness.",
   provable="Nothing.",
   statement="An automated access lifecycle with cross-system reconciliation is planned and not yet in place.",
   kind="planned", controls=["HR-002"], evrs=["HR-004"],
   requirements=["SOC2-010"], freshness="P1D", mechanism="continuous-automated", automation="full",
   impl="medium", recur="low",
   qd=dict(sub="Onboarding and offboarding", concern="Access ends when it should, everywhere.",
           risk="Former personnel or stale credentials retain access to customer data or systems.",
           src=[S("SRC-AICPA-TSC", "CC6.2"), S("SRC-NIST-SP800-53-R5", "PS-4"), S("SRC-ISO-27001-2022", "A.6.5"), S("SRC-CSA-CCM-V4", "HRS-06"), S("SRC-SA-SIG", rel="informed-by")],
           ind=ALLI, prod=ALLP, rc="certification-criteria", imp="high"),
   questions=[
    Q("How quickly is access revoked on voluntary and involuntary termination? Provide evidence for recent departures.",
      ["What is your deprovisioning SLA?"], imp="critical"),
    Q("How do you ensure every form of access is revoked, including cloud console accounts, code hosting, API keys, personal access tokens and AI tool accounts, not only the primary login?",
      ["Do you revoke tokens and keys at offboarding?"]),
    Q("How are company devices and any customer data recovered from departing personnel?",
      ["Describe asset return at termination."], src=[S("SRC-ISO-27001-2022", "A.5.11"), S("SRC-CSA-CCM-V4", "HRS-05")], imp="medium"),
    Q("How do you adjust access when personnel change roles so that they do not accumulate privileges?",
      ["How do you prevent privilege creep?"], src=[S("SRC-NIST-SP800-53-R5", "PS-5")], imp="medium"),
    Q("How do you ensure contractor access ends when an engagement ends, even without HR involvement?",
      ["Do contractor accounts expire automatically?"], src=[S("SRC-NIST-SP800-53-R5", "PS-7")]),
   ])

au(HRC, 5, title="AI agents as workforce: scope, permissions, accountability and revocation",
   status="proposed-target-state",
   rationale="AI agents perform engineering and research work in Echelon repositories (Praxis provenance records agent actors). Unbound requires agents to be attributable, bounded, monitored and interruptible (SOC2-017), forbids agents from granting themselves permissions or approving their own consequential actions (GOV-AUTH-003), limits agents to propose and prepare (UNB-AGT-002, CNV-AIO-001) and requires prohibited tools to be removed by the tool broker rather than by prompts (UNB-AGT-003). None of this is operating for a production service.",
   target="AI agents are treated as non-human workforce members with registered identities, a named accountable human owner, a scope statement and least-privilege tool and data permissions enforced by a tool broker, not by prompt instructions. Agents cannot grant themselves access, approve their own changes, merge to protected branches without human or independent-gate approval, or execute consequential actions reserved to humans. Agents have no standing access to production customer data; any access is just-in-time, purpose-bound and logged. Agent credentials and integrations are revoked through the same lifecycle as human leavers. The accountable owner answers for agent outcomes.",
   current="AI agents do repository engineering and research work. Their permissions, production access and revocation are not documented in records located.",
   intended="Register agent identities and owners; implement tool broker and approval separation for Unbound operations.",
   provable="Praxis provenance identifies agent contributions in repositories; nothing proves permission bounds.",
   statement="Echelon uses AI agents for engineering and research work. A governed model for agent identities, permissions and accountability is planned; agents are intended never to hold standing access to customer production data.",
   kind="planned", controls=["HR-004", "HR-006", "HR-002"], evrs=["HR-006", "HR-004"],
   requirements=["SOC2-017", "GOV-AUTH-003", "UNB-AGT-002", "UNB-AGT-003", "CNV-AIO-001"], freshness="per-event", mechanism="event-driven-automated",
   automation="full", impl="medium", recur="low",
   challenge=CH(
     customer_intent="Work done by AI is controlled at least as well as work done by people.",
     adverse_outcome="An AI agent exfiltrates data, introduces malicious or defective code, or takes an unauthorized consequential action.",
     conventional_control_effectiveness="Personnel controls (background checks, training, NDAs) do not apply to AI agents; questionnaires that ask only about humans miss the risk.",
     legally_required="No specific law; AI risk frameworks and some state AI laws address automated decisions, not engineering agents.",
     contractually_required="Emerging; increasingly asked in AI addenda.",
     historical_convention="None established; treated as tools.",
     architectural_elimination="Tool broker removes prohibited tools; authority matrix refuses agent execution of reserved actions; agents have no production data path by default.",
     automatic_enforcement="Branch protection and independent gates prevent self-approval.",
     continuous_evidence="Provenance and tool-invocation logs per agent run.",
     stronger_alternative="Structural permission bounds and provenance rather than human-style vetting.",
     alternative_verifiable="Yes, by inspecting broker configuration, branch protection and logs.",
     customer_acceptance_likelihood="Likely where customers are educated; uncertain where questionnaires assume human workforce only.",
     invalidating_conditions="Agents run with a human's broad credentials; prompts relied on for restriction.",
     conventional_cost="Not applicable.",
     alternative_cost="Medium engineering.",
     alternative_risks="Prompt injection through data the agent reads; model provider compromise.",
     supporting_arguments=["Agent permissions can be narrower and better logged than human permissions."],
     opposing_arguments=["Customers may be uncomfortable with extensive agent involvement regardless of controls.", "A single human accountable owner for many agents may be overstretched."],
     technical_effectiveness="stronger", institutional_acceptance="uncertain"),
   qd=dict(sub="AI agents as workforce", concern="AI agents doing work for the vendor are bounded, accountable and revocable.",
           risk="AI agents act beyond authority, access customer data inappropriately, or cause harm with no accountable human.",
           src=[D("SRC-ECH-UNB-SOC2-DIRECTIVE"), D("SRC-ECH-UNB-BASELINE"), S("SRC-OWASP-AGENTIC-AI", rel="informed-by"), S("SRC-NIST-AI-RMF-1.0", rel="informed-by"), S("SRC-ISO-42001-2023", rel="informed-by")],
           ind=ALLI, prod=ALLP, rc="customer-preference", imp="high"),
   questions=[
    Q("Do AI agents perform engineering, operations or support work with access to your code, systems or customer data? Describe their scope.",
      ["Do you use autonomous AI agents in your operations?"], imp="critical"),
    Q("What permissions do AI agents hold, and what prevents them from granting themselves additional access or approving their own work?",
      ["Can an AI agent approve its own pull request?"]),
    Q("Can AI agents access production customer data? If so, under what conditions, approvals and logging?",
      ["Do AI agents see our data?"], imp="critical"),
    Q("How do you revoke an AI agent's or AI tool's credentials, tokens and integrations when it is retired or compromised?",
      ["How do you offboard an AI agent?"], src=[D("SRC-ECH-UNB-SOC2-DIRECTIVE"), S("SRC-AICPA-TSC", "CC6.2", "informed-by")]),
    Q("Who is accountable when an AI agent causes an error or incident, and how is that accountability recorded?",
      ["Who answers for AI agent mistakes?"], imp="medium"),
   ])

au(HRC, 6, title="Attribution of AI agent and human work through provenance records",
   status="implemented-not-independently-verified",
   rationale="Within repositories governed by Praxis, execution identity records actor kind (agent, human, automation, unknown), stable actor id, provider, model and runtime per execution, and artifact provenance records each contribution keyed by execution (docs/agent-provenance.md in this repository; provenance blocks in this repository's AGENTS.md show agent contributions). Scope is repository work only, not production operations, and the mechanism relies on declared or detected identity and has not been independently reviewed.",
   target="Every change to code, configuration, policy, agent instructions and evidence is attributed to a stable actor (human, agent with provider, model and runtime, or automation) and to a specific execution, so a customer or auditor can see which work in a release was done by AI agents and which by humans, who approved it, and which instruction and tool configuration the agent ran under. Agent instructions, guardrails and tool permissions are version-controlled and changed only through reviewed changes.",
   current="Praxis records actor and execution identity for repository work in Praxis-governed repositories. Agent instruction files (such as AGENTS.md) are version-controlled. This is not yet applied to production operations, and agent permission configuration is not centrally recorded.",
   intended="Extend provenance to release manifests and to Unbound operational agents.",
   provable="Praxis execution and artifact provenance records in repositories, and Git history of agent instruction files.",
   statement="In Praxis-governed Echelon repositories, work is attributed to the human, AI agent (with provider, model and runtime where known) or automation that performed it and to the specific execution. This is first-party tooling, applies to repository work rather than a production service, and has not been independently verified.",
   kind="qualified-current-fact", indep="first-party", controls=["HR-003"], evrs=["HR-005"],
   requirements=["SOC2-017", "SOC2-002"], freshness="per-event", mechanism="event-driven-automated", automation="full",
   disc="authenticated-prospect", impl="none", recur="low",
   residual=["Identity is declared or detected from environment; a misconfigured runtime records 'unknown' rather than the true actor.",
             "Records live in repositories whose administrators could alter them; tamper evidence is not established."],
   qd=dict(sub="AI agent attribution", concern="The customer can tell who or what did the work.",
           risk="Agent-produced changes are indistinguishable from human work, defeating review and accountability.",
           src=[D("SRC-ECH-UNB-SOC2-DIRECTIVE"), S("SRC-NIST-SP800-218A", rel="informed-by"), S("SRC-SLSA", rel="informed-by")],
           ind=ALLI, prod=ALLP, rc="customer-preference", imp="medium"),
   questions=[
    Q("How is each AI agent action attributed to a specific agent identity, execution and accountable human?",
      ["Can you show which agent made a given change?"], imp="high"),
    Q("Are AI agents' instructions, guardrails and tool permissions version-controlled and reviewed like code?",
      ["How do you manage changes to agent prompts and tools?"]),
    Q("Can you produce a record showing which work in a given release was performed by AI agents, which by humans, and who approved it?",
      ["What share of your code is AI-written, and is it reviewed?"]),
   ])

